"""Value analysis CPAs and the generic CPA worklist algorithm.

This module implements cpachecker_v0:

- ``LocationCPA``      : tracks the current CFA location (program counter).
- ``ExplicitValueCPA`` : tracks concrete integer values for all variables
                         (``TOP`` marks an unknown / nondeterministic value).
- ``CompositeCPA``     : the product analysis of location + explicit values.
- ``cpa_algorithm``    : the generic CPA reachability worklist algorithm.
- ``run_value_analysis``: entry point used by ``cpachecker_main.py``.

Only the Python standard library is used.  Expressions are evaluated with the
helpers in :mod:`cpachecker.expression`.
"""

from __future__ import annotations

import time
from typing import Any, Optional

from cpachecker.cfa import CFA, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import evaluate_condition, evaluate_expression
from cpachecker.result import Verdict, VerificationResult


# ---------------------------------------------------------------------------
# TOP sentinel
# ---------------------------------------------------------------------------
class _Top:
    """Singleton representing an unknown / nondeterministic value."""

    _instance: Optional["_Top"] = None

    def __new__(cls) -> "_Top":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:  # pragma: no cover - trivial
        return "TOP"

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, _Top)

    def __hash__(self) -> int:
        return hash("cpachecker.TOP")


TOP = _Top()


def state_location(state: AbstractState) -> int:
    """Return the CFA node id that an abstract state is located at."""
    return state.location_id  # type: ignore[attr-defined]


# ---------------------------------------------------------------------------
# Generic (empty) precision
# ---------------------------------------------------------------------------
class EmptyPrecision(Precision):
    def __repr__(self) -> str:  # pragma: no cover - trivial
        return "EmptyPrecision()"

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, EmptyPrecision)

    def __hash__(self) -> int:
        return hash("EmptyPrecision")


# ---------------------------------------------------------------------------
# Location CPA
# ---------------------------------------------------------------------------
class LocationState(AbstractState):
    """Abstract state of the location CPA: simply the CFA node id."""

    def __init__(self, node_id: int):
        self.node_id = node_id

    @property
    def location_id(self) -> int:
        return self.node_id

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, LocationState) and self.node_id == other.node_id

    def __hash__(self) -> int:
        return hash(("LocationState", self.node_id))

    def __repr__(self) -> str:
        return f"Loc({self.node_id})"


class LocationDomain(AbstractDomain):
    def is_less_or_equal(self, state1: LocationState, state2: LocationState) -> bool:
        return state1 == state2

    def join(self, state1: LocationState, state2: LocationState) -> LocationState:
        if state1 == state2:
            return state1
        return self.get_top()

    def get_top(self) -> LocationState:
        return LocationState(-1)

    def get_bottom(self) -> LocationState:  # pragma: no cover - not used
        return LocationState(-2)


class LocationTransferRelation(TransferRelation):
    """Move to the successor node along the given edge."""

    def get_abstract_successors(self, state, precision, edge):
        return [LocationState(edge.target)]


class LocationMergeOperator(MergeOperator):
    """"sep" semantics: never merge distinct locations."""

    def merge(self, state1, state2, precision):
        return state2


class LocationStopOperator(StopOperator):
    """Covered iff the exact same location is already in the reached set."""

    def stop(self, state, reached, precision):
        return any(state == r for r in reached)


class LocationCPA(ConfigurableProgramAnalysis):
    def __init__(self) -> None:
        self._domain = LocationDomain()
        self._transfer = LocationTransferRelation()
        self._merge = LocationMergeOperator()
        self._stop = LocationStopOperator()

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return LocationState(node_id)

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


# ---------------------------------------------------------------------------
# Explicit value CPA
# ---------------------------------------------------------------------------
class ExplicitValueState(AbstractState):
    """Abstract state mapping variable names to concrete ints or ``TOP``."""

    def __init__(self, values: Optional[dict] = None):
        self.values: dict = dict(values) if values else {}

    @property
    def location_id(self) -> int:  # pragma: no cover - composite provides it
        raise AttributeError("ExplicitValueState has no location")

    def get(self, var: str):
        return self.values.get(var, TOP)

    def assign(self, var: str, value) -> "ExplicitValueState":
        new_values = dict(self.values)
        new_values[var] = value
        return ExplicitValueState(new_values)

    def concrete_env(self) -> dict:
        """Environment with only the known (concrete int) bindings."""
        return {k: v for k, v in self.values.items() if isinstance(v, int)}

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, ExplicitValueState) and self.values == other.values

    def __hash__(self) -> int:
        return hash(("ExplicitValueState", frozenset(self.values.items())))

    def __repr__(self) -> str:
        inner = ", ".join(f"{k}={v!r}" for k, v in sorted(self.values.items()))
        return f"ValState({inner})"


class ExplicitValueDomain(AbstractDomain):
    def is_less_or_equal(self, state1, state2) -> bool:
        # state1 ⊑ state2 iff every variable of state1 is either matched
        # exactly by state2 or is TOP (less precise) in state2.
        for var in state1.values:
            v1 = state1.values[var]
            v2 = state2.get(var)
            if v2 is TOP:
                continue
            if v1 is TOP or v1 != v2:
                return False
        return True

    def join(self, state1, state2):
        joined = {}
        for var in set(state1.values) | set(state2.values):
            v1, v2 = state1.get(var), state2.get(var)
            joined[var] = v1 if v1 == v2 else TOP
        return ExplicitValueState(joined)

    def get_top(self):
        return ExplicitValueState({})

    def get_bottom(self):  # pragma: no cover - not used
        return None


class ExplicitValueTransferRelation(TransferRelation):
    """Concrete evaluation of assignments / assume-edge feasibility."""

    def get_abstract_successors(self, state, precision, edge):
        env = state.concrete_env()
        etype = edge.edge_type

        if etype == EdgeType.ASSIGNMENT:
            value = evaluate_expression(edge.expression, env)
            if value is None:
                value = TOP
            return [state.assign(edge.variable, value)]

        if etype == EdgeType.ASSUME_TRUE:
            cond = evaluate_condition(edge.expression, env)
            if cond is False:
                return []  # infeasible path
            return [ExplicitValueState(state.values)]

        if etype == EdgeType.ASSUME_FALSE:
            cond = evaluate_condition(edge.expression, env)
            if cond is True:
                return []  # infeasible path
            return [ExplicitValueState(state.values)]

        # ASSERT / FUNCTION_CALL / BLANK edges do not modify the valuation.
        return [ExplicitValueState(state.values)]


class ExplicitValueMergeOperator(MergeOperator):
    """"sep" semantics: keep every valuation separate."""

    def merge(self, state1, state2, precision):
        return state2


class ExplicitValueStopOperator(StopOperator):
    def __init__(self, domain: ExplicitValueDomain):
        self._domain = domain

    def stop(self, state, reached, precision):
        return any(self._domain.is_less_or_equal(state, r) for r in reached)


class ExplicitValueCPA(ConfigurableProgramAnalysis):
    def __init__(self, variables):
        self._variables = list(variables)
        self._domain = ExplicitValueDomain()
        self._transfer = ExplicitValueTransferRelation()
        self._merge = ExplicitValueMergeOperator()
        self._stop = ExplicitValueStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return ExplicitValueState({v: TOP for v in self._variables})

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


# ---------------------------------------------------------------------------
# Composite CPA (product of component CPAs)
# ---------------------------------------------------------------------------
class CompositeState(AbstractState):
    """Tuple of component states; the first component is the location."""

    def __init__(self, components):
        self.components = tuple(components)

    @property
    def location_id(self) -> int:
        return self.components[0].node_id

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, CompositeState) and self.components == other.components

    def __hash__(self) -> int:
        return hash(("CompositeState", self.components))

    def __repr__(self) -> str:
        return "Composite(" + ", ".join(repr(c) for c in self.components) + ")"


class CompositeDomain(AbstractDomain):
    def __init__(self, domains):
        self._domains = list(domains)

    def is_less_or_equal(self, state1, state2) -> bool:
        return all(
            d.is_less_or_equal(c1, c2)
            for d, c1, c2 in zip(self._domains, state1.components, state2.components)
        )

    def join(self, state1, state2):
        return CompositeState(
            [d.join(c1, c2)
             for d, c1, c2 in zip(self._domains, state1.components, state2.components)]
        )

    def get_top(self):
        return CompositeState([d.get_top() for d in self._domains])

    def get_bottom(self):  # pragma: no cover - not used
        return None


class CompositeTransferRelation(TransferRelation):
    def __init__(self, transfers):
        self._transfers = list(transfers)

    def get_abstract_successors(self, state, precision, edge):
        # Compute the successor of every component; if any component finds the
        # edge infeasible (empty successor list) the whole edge is infeasible.
        component_successors = []
        for transfer, component in zip(self._transfers, state.components):
            succs = transfer.get_abstract_successors(component, precision, edge)
            if not succs:
                return []
            component_successors.append(succs)

        # Product of the component successors (each is a singleton here).
        results = [CompositeState([])]
        for succs in component_successors:
            results = [
                CompositeState(list(base.components) + [s])
                for base in results
                for s in succs
            ]
        return results


class CompositeMergeOperator(MergeOperator):
    def __init__(self, merges):
        self._merges = list(merges)

    def merge(self, state1, state2, precision):
        # Component-wise merge ("sep" for all components => returns state2).
        merged = [
            m.merge(c1, c2, precision)
            for m, c1, c2 in zip(self._merges, state1.components, state2.components)
        ]
        if all(mc is c2 or mc == c2 for mc, c2 in zip(merged, state2.components)):
            return state2
        return CompositeState(merged)


class CompositeStopOperator(StopOperator):
    def __init__(self, domain: CompositeDomain):
        self._domain = domain

    def stop(self, state, reached, precision):
        return any(self._domain.is_less_or_equal(state, r) for r in reached)


class CompositeCPA(ConfigurableProgramAnalysis):
    """Product CPA combining several component CPAs."""

    def __init__(self, cpas):
        self._cpas = list(cpas)
        self._domain = CompositeDomain([c.get_abstract_domain() for c in self._cpas])
        self._transfer = CompositeTransferRelation(
            [c.get_transfer_relation() for c in self._cpas])
        self._merge = CompositeMergeOperator(
            [c.get_merge_operator() for c in self._cpas])
        self._stop = CompositeStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return CompositeState([c.get_initial_state(node_id) for c in self._cpas])

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


# ---------------------------------------------------------------------------
# Generic CPA worklist algorithm
# ---------------------------------------------------------------------------
def cpa_algorithm(cpa: ConfigurableProgramAnalysis, cfa: CFA,
                  timelimit: int = 900) -> VerificationResult:
    """Reachability analysis with the CPA worklist algorithm.

    Explores the reachable abstract state space; reports ``FALSE`` as soon as
    an error location is reached and ``TRUE`` once the state space is fully
    explored without hitting an error.
    """
    start_time = time.time()

    transfer = cpa.get_transfer_relation()
    merge = cpa.get_merge_operator()
    stop = cpa.get_stop_operator()
    precision = cpa.get_initial_precision()

    initial = cpa.get_initial_state(cfa.entry_node)

    reached: dict[int, list] = {}

    def _reached_list(node_id: int) -> list:
        return reached.setdefault(node_id, [])

    worklist: list = [initial]
    _reached_list(state_location(initial)).append(initial)

    num_iterations = 0
    max_states = 0

    while worklist:
        if time.time() - start_time > timelimit:
            return VerificationResult(
                verdict=Verdict.UNKNOWN,
                statistics={"reason": "timeout", "iterations": num_iterations},
            )

        state = worklist.pop()
        num_iterations += 1
        loc = state_location(state)

        for edge in cfa.get_successors(loc):
            successors = transfer.get_abstract_successors(state, precision, edge)
            for succ in successors:
                succ_loc = state_location(succ)

                if cfa.nodes[succ_loc].is_error:
                    return VerificationResult(
                        verdict=Verdict.FALSE,
                        property_violated="assertion",
                        statistics={
                            "iterations": num_iterations,
                            "reached_states": sum(len(v) for v in reached.values()),
                            "error_location": succ_loc,
                        },
                    )

                reached_list = _reached_list(succ_loc)

                # --- merge step -------------------------------------------
                merged_state = succ
                replaced = False
                for existing in list(reached_list):
                    merged = merge.merge(merged_state, existing, precision)
                    if merged is not existing and merged != existing:
                        # `existing` grew to `merged`; replace it in place.
                        idx = reached_list.index(existing)
                        reached_list[idx] = merged
                        try:
                            widx = worklist.index(existing)
                            worklist[widx] = merged
                        except ValueError:
                            pass
                        merged_state = merged
                        replaced = True
                        break
                if replaced:
                    # The successor was merged into an existing state.
                    continue

                # --- stop step --------------------------------------------
                if not stop.stop(merged_state, reached_list, precision):
                    reached_list.append(merged_state)
                    worklist.append(merged_state)

        max_states = max(max_states, sum(len(v) for v in reached.values()))

    return VerificationResult(
        verdict=Verdict.TRUE,
        statistics={
            "iterations": num_iterations,
            "reached_states": sum(len(v) for v in reached.values()),
        },
    )


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def run_value_analysis(cfa: CFA, timelimit: int = 900) -> VerificationResult:
    """Run explicit-value analysis on ``cfa`` and return the verdict."""
    cpa = CompositeCPA([LocationCPA(), ExplicitValueCPA(cfa.variables)])
    result = cpa_algorithm(cpa, cfa, timelimit)
    result.statistics.setdefault("analysis", "valueAnalysis")
    return result

