"""Value analysis CPAs and the generic CPA worklist algorithm.

This module implements cpachecker_v0:

- ``LocationCPA``      : tracks the current CFA location (program counter).
- ``ExplicitValueCPA`` : tracks concrete integer values for all variables
                         (``TOP`` marks an unknown / nondeterministic value).
- ``CompositeCPA``     : the product analysis of location + explicit values.
- ``cpa_algorithm``    : the generic CPA reachability worklist algorithm.
- ``run_value_analysis``: entry point used by ``cpachecker_main.py``.

Only the Python standard library is used.  Expressions are evaluated with the
helpers in :mod:`cpachecker.expression`.
"""

from __future__ import annotations

import time
from typing import Any, Optional

from cpachecker.cfa import CFA, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import evaluate_condition, evaluate_expression
from cpachecker.result import Verdict, VerificationResult


# ---------------------------------------------------------------------------
# TOP sentinel
# ---------------------------------------------------------------------------
class _Top:
    """Singleton representing an unknown / nondeterministic value."""

    _instance: Optional["_Top"] = None

    def __new__(cls) -> "_Top":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:  # pragma: no cover - trivial
        return "TOP"

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, _Top)

    def __hash__(self) -> int:
        return hash("cpachecker.TOP")


TOP = _Top()


def state_location(state: AbstractState) -> int:
    """Return the CFA node id that an abstract state is located at."""
    return state.location_id  # type: ignore[attr-defined]


# ---------------------------------------------------------------------------
# Generic (empty) precision
# ---------------------------------------------------------------------------
class EmptyPrecision(Precision):
    def __repr__(self) -> str:  # pragma: no cover - trivial
        return "EmptyPrecision()"

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, EmptyPrecision)

    def __hash__(self) -> int:
        return hash("EmptyPrecision")


# ---------------------------------------------------------------------------
# Location CPA
# ---------------------------------------------------------------------------
class LocationState(AbstractState):
    """Abstract state of the location CPA: simply the CFA node id."""

    def __init__(self, node_id: int):
        self.node_id = node_id

    @property
    def location_id(self) -> int:
        return self.node_id

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, LocationState) and self.node_id == other.node_id

    def __hash__(self) -> int:
        return hash(("LocationState", self.node_id))

    def __repr__(self) -> str:
        return f"Loc({self.node_id})"


class LocationDomain(AbstractDomain):
    def is_less_or_equal(self, state1: LocationState, state2: LocationState) -> bool:
        return state1 == state2

    def join(self, state1: LocationState, state2: LocationState) -> LocationState:
        if state1 == state2:
            return state1
        return self.get_top()

    def get_top(self) -> LocationState:
        return LocationState(-1)

    def get_bottom(self) -> LocationState:  # pragma: no cover - not used
        return LocationState(-2)


class LocationTransferRelation(TransferRelation):
    """Move to the successor node along the given edge."""

    def get_abstract_successors(self, state, precision, edge):
        return [LocationState(edge.target)]


class LocationMergeOperator(MergeOperator):
    """"sep" semantics: never merge distinct locations."""

    def merge(self, state1, state2, precision):
        return state2


class LocationStopOperator(StopOperator):
    """Covered iff the exact same location is already in the reached set."""

    def stop(self, state, reached, precision):
        return any(state == r for r in reached)


class LocationCPA(ConfigurableProgramAnalysis):
    def __init__(self) -> None:
        self._domain = LocationDomain()
        self._transfer = LocationTransferRelation()
        self._merge = LocationMergeOperator()
        self._stop = LocationStopOperator()

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return LocationState(node_id)

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


# ---------------------------------------------------------------------------
# Explicit value CPA
# ---------------------------------------------------------------------------
class ExplicitValueState(AbstractState):
    """Abstract state mapping variable names to concrete ints or ``TOP``."""

    def __init__(self, values: Optional[dict] = None):
        self.values: dict = dict(values) if values else {}

    @property
    def location_id(self) -> int:  # pragma: no cover - composite provides it
        raise AttributeError("ExplicitValueState has no location")

    def get(self, var: str):
        return self.values.get(var, TOP)

    def assign(self, var: str, value) -> "ExplicitValueState":
        new_values = dict(self.values)
        new_values[var] = value
        return ExplicitValueState(new_values)

    def concrete_env(self) -> dict:
        """Environment with only the known (concrete int) bindings."""
        return {k: v for k, v in self.values.items() if isinstance(v, int)}

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, ExplicitValueState) and self.values == other.values

    def __hash__(self) -> int:
        return hash(("ExplicitValueState", frozenset(self.values.items())))

    def __repr__(self) -> str:
        inner = ", ".join(f"{k}={v!r}" for k, v in sorted(self.values.items()))
        return f"ValState({inner})"


class ExplicitValueDomain(AbstractDomain):
    def is_less_or_equal(self, state1, state2) -> bool:
        # state1 ⊑ state2 iff every variable of state1 is either matched
        # exactly by state2 or is TOP (less precise) in state2.
        for var in state1.values:
            v1 = state1.values[var]
            v2 = state2.get(var)
            if v2 is TOP:
                continue
            if v1 is TOP or v1 != v2:
                return False
        return True

    def join(self, state1, state2):
        joined = {}
        for var in set(state1.values) | set(state2.values):
            v1, v2 = state1.get(var), state2.get(var)
            joined[var] = v1 if v1 == v2 else TOP
        return ExplicitValueState(joined)

    def get_top(self):
        return ExplicitValueState({})

    def get_bottom(self):  # pragma: no cover - not used
        return None


class ExplicitValueTransferRelation(TransferRelation):
    """Concrete evaluation of assignments / assume-edge feasibility."""

    def get_abstract_successors(self, state, precision, edge):
        env = state.concrete_env()
        etype = edge.edge_type

        if etype == EdgeType.ASSIGNMENT:
            value = evaluate_expression(edge.expression, env)
            if value is None:
                value = TOP
            return [state.assign(edge.variable, value)]

        if etype == EdgeType.ASSUME_TRUE:
            cond = evaluate_condition(edge.expression, env)
            if cond is False:
                return []  # infeasible path
            return [ExplicitValueState(state.values)]

        if etype == EdgeType.ASSUME_FALSE:
            cond = evaluate_condition(edge.expression, env)
            if cond is True:
                return []  # infeasible path
            return [ExplicitValueState(state.values)]

        # ASSERT / FUNCTION_CALL / BLANK edges do not modify the valuation.
        return [ExplicitValueState(state.values)]


class ExplicitValueMergeOperator(MergeOperator):
    """"sep" semantics: keep every valuation separate."""

    def merge(self, state1, state2, precision):
        return state2


class ExplicitValueStopOperator(StopOperator):
    def __init__(self, domain: ExplicitValueDomain):
        self._domain = domain

    def stop(self, state, reached, precision):
        return any(self._domain.is_less_or_equal(state, r) for r in reached)


class ExplicitValueCPA(ConfigurableProgramAnalysis):
    def __init__(self, variables):
        self._variables = list(variables)
        self._domain = ExplicitValueDomain()
        self._transfer = ExplicitValueTransferRelation()
        self._merge = ExplicitValueMergeOperator()
        self._stop = ExplicitValueStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return ExplicitValueState({v: TOP for v in self._variables})

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


# ---------------------------------------------------------------------------
# Composite CPA (product of component CPAs)
# ---------------------------------------------------------------------------
class CompositeState(AbstractState):
    """Tuple of component states; the first component is the location."""

    def __init__(self, components):
        self.components = tuple(components)

    @property
    def location_id(self) -> int:
        return self.components[0].node_id

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, CompositeState) and self.components == other.components

    def __hash__(self) -> int:
        return hash(("CompositeState", self.components))

    def __repr__(self) -> str:
        return "Composite(" + ", ".join(repr(c) for c in self.components) + ")"


class CompositeDomain(AbstractDomain):
    def __init__(self, domains):
        self._domains = list(domains)

    def is_less_or_equal(self, state1, state2) -> bool:
        return all(
            d.is_less_or_equal(c1, c2)
            for d, c1, c2 in zip(self._domains, state1.components, state2.components)
        )

    def join(self, state1, state2):
        return CompositeState(
            [d.join(c1, c2)
             for d, c1, c2 in zip(self._domains, state1.components, state2.components)]
        )

    def get_top(self):
        return CompositeState([d.get_top() for d in self._domains])

    def get_bottom(self):  # pragma: no cover - not used
        return None


class CompositeTransferRelation(TransferRelation):
    def __init__(self, transfers):
        self._transfers = list(transfers)

    def get_abstract_successors(self, state, precision, edge):
        # Compute the successor of every component; if any component finds the
        # edge infeasible (empty successor list) the whole edge is infeasible.
        component_successors = []
        for transfer, component in zip(self._transfers, state.components):
            succs = transfer.get_abstract_successors(component, precision, edge)
            if not succs:
                return []
            component_successors.append(succs)

        # Product of the component successors (each is a singleton here).
        results = [CompositeState([])]
        for succs in component_successors:
            results = [
                CompositeState(list(base.components) + [s])
                for base in results
                for s in succs
            ]
        return results


class CompositeMergeOperator(MergeOperator):
    def __init__(self, merges):
        self._merges = list(merges)

    def merge(self, state1, state2, precision):
        # Component-wise merge ("sep" for all components => returns state2).
        merged = [
            m.merge(c1, c2, precision)
            for m, c1, c2 in zip(self._merges, state1.components, state2.components)
        ]
        if all(mc is c2 or mc == c2 for mc, c2 in zip(merged, state2.components)):
            return state2
        return CompositeState(merged)


class CompositeStopOperator(StopOperator):
    def __init__(self, domain: CompositeDomain):
        self._domain = domain

    def stop(self, state, reached, precision):
        return any(self._domain.is_less_or_equal(state, r) for r in reached)


class CompositeCPA(ConfigurableProgramAnalysis):
    """Product CPA combining several component CPAs."""

    def __init__(self, cpas):
        self._cpas = list(cpas)
        self._domain = CompositeDomain([c.get_abstract_domain() for c in self._cpas])
        self._transfer = CompositeTransferRelation(
            [c.get_transfer_relation() for c in self._cpas])
        self._merge = CompositeMergeOperator(
            [c.get_merge_operator() for c in self._cpas])
        self._stop = CompositeStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return CompositeState([c.get_initial_state(node_id) for c in self._cpas])

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


# ---------------------------------------------------------------------------
# Generic CPA worklist algorithm
# ---------------------------------------------------------------------------
def cpa_algorithm(cpa: ConfigurableProgramAnalysis, cfa: CFA,
                  timelimit: int = 900) -> VerificationResult:
    """Reachability analysis with the CPA worklist algorithm.

    Explores the reachable abstract state space; reports ``FALSE`` as soon as
    an error location is reached and ``TRUE`` once the state space is fully
    explored without hitting an error.
    """
    start_time = time.time()

    transfer = cpa.get_transfer_relation()
    merge = cpa.get_merge_operator()
    stop = cpa.get_stop_operator()
    precision = cpa.get_initial_precision()

    initial = cpa.get_initial_state(cfa.entry_node)

    reached: dict[int, list] = {}

    def _reached_list(node_id: int) -> list:
        return reached.setdefault(node_id, [])

    worklist: list = [initial]
    _reached_list(state_location(initial)).append(initial)

    num_iterations = 0
    max_states = 0

    while worklist:
        if time.time() - start_time > timelimit:
            return VerificationResult(
                verdict=Verdict.UNKNOWN,
                statistics={"reason": "timeout", "iterations": num_iterations},
            )

        state = worklist.pop()
        num_iterations += 1
        loc = state_location(state)

        for edge in cfa.get_successors(loc):
            successors = transfer.get_abstract_successors(state, precision, edge)
            for succ in successors:
                succ_loc = state_location(succ)

                if cfa.nodes[succ_loc].is_error:
                    return VerificationResult(
                        verdict=Verdict.FALSE,
                        property_violated="assertion",
                        statistics={
                            "iterations": num_iterations,
                            "reached_states": sum(len(v) for v in reached.values()),
                            "error_location": succ_loc,
                        },
                    )

                reached_list = _reached_list(succ_loc)

                # --- merge step -------------------------------------------
                merged_state = succ
                replaced = False
                for existing in list(reached_list):
                    merged = merge.merge(merged_state, existing, precision)
                    if merged is not existing and merged != existing:
                        # `existing` grew to `merged`; replace it in place.
                        idx = reached_list.index(existing)
                        reached_list[idx] = merged
                        try:
                            widx = worklist.index(existing)
                            worklist[widx] = merged
                        except ValueError:
                            pass
                        merged_state = merged
                        replaced = True
                        break
                if replaced:
                    # The successor was merged into an existing state.
                    continue

                # --- stop step --------------------------------------------
                if not stop.stop(merged_state, reached_list, precision):
                    reached_list.append(merged_state)
                    worklist.append(merged_state)

        max_states = max(max_states, sum(len(v) for v in reached.values()))

    return VerificationResult(
        verdict=Verdict.TRUE,
        statistics={
            "iterations": num_iterations,
            "reached_states": sum(len(v) for v in reached.values()),
        },
    )


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def run_value_analysis(cfa: CFA, timelimit: int = 900) -> VerificationResult:
    """Run explicit-value analysis on ``cfa`` and return the verdict."""
    cpa = CompositeCPA([LocationCPA(), ExplicitValueCPA(cfa.variables)])
    result = cpa_algorithm(cpa, cfa, timelimit)
    result.statistics.setdefault("analysis", "valueAnalysis")
    return result

args.content:
"""Predicate analysis with symbolic constraints and path-feasibility checking.

This module implements cpachecker_v1.

Instead of tracking concrete values, the predicate analysis performs *symbolic
execution*: every program variable maps to an affine expression over input
symbols (one fresh symbol per ``__VERIFIER_nondet_*`` call), and every assume
edge adds a path constraint.  A lightweight constraint solver
(:class:`PathFeasibilityChecker`) decides satisfiability of the accumulated
linear arithmetic constraints, which is used both for pruning infeasible paths
and for deciding whether an error location is reachable.

Termination on loops is achieved through a *predicate abstraction* layer: from
the precise symbolic state we derive, for a fixed set of program predicates
(the conditions occurring in the CFA), which of them are known to hold.  A
state is subsumed (coverage / stop operator) as soon as a previously explored
state at the same location knows a subset of these predicates.

Components:

- :class:`PathFeasibilityChecker`  - linear-arithmetic satisfiability checker.
- :class:`PredicateAbstractState`  - symbolic store + path constraints.
- :class:`PredicateTransferRelation` - strongest-postcondition style transfer.
- :class:`PredicateCPA`            - the CPA wrapping the above.
- :func:`run_predicate_analysis`   - entry point.
"""

from __future__ import annotations

import ast
import re
from fractions import Fraction

from cpachecker.cfa import CFA, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.analyses.value_analysis import (
    CompositeCPA,
    EmptyPrecision,
    LocationCPA,
    cpa_algorithm,
)
from cpachecker.result import Verdict, VerificationResult

_CONST = ""  # reserved key holding the constant summand of an affine form


# ---------------------------------------------------------------------------
# Affine forms: dict {symbol: coeff, _CONST: const}
# ---------------------------------------------------------------------------
def aff_const(c: int) -> dict:
    return {_CONST: c} if c != 0 else {}


def aff_var(symbol: str) -> dict:
    return {symbol: 1}


def aff_neg(a: dict) -> dict:
    return {k: -v for k, v in a.items()}


def _clean(a: dict) -> dict:
    return {k: v for k, v in a.items() if v != 0}


def aff_add(a: dict, b: dict) -> dict:
    r = dict(a)
    for k, v in b.items():
        r[k] = r.get(k, 0) + v
    return _clean(r)


def aff_sub(a: dict, b: dict) -> dict:
    return aff_add(a, aff_neg(b))


def aff_scale(a: dict, k: int) -> dict:
    if k == 0:
        return {}
    return _clean({key: v * k for key, v in a.items()})


def aff_add_const(a: dict, c) -> dict:
    r = dict(a)
    r[_CONST] = r.get(_CONST, 0) + c
    return _clean(r)


def aff_is_const(a: dict) -> bool:
    return all(k == _CONST for k in a)


# ---------------------------------------------------------------------------
# Symbol generation
# ---------------------------------------------------------------------------
class SymbolGen:
    """Produces fresh symbols for nondeterministic / unknown values."""

    def __init__(self) -> None:
        self._counter = 0

    def fresh(self, prefix: str = "s") -> str:
        self._counter += 1
        return f"#{prefix}{self._counter}"


# ---------------------------------------------------------------------------
# Expression -> affine form / constraint (via the ``ast`` module)
# ---------------------------------------------------------------------------
_NOT_RE = re.compile(r"(?<![!<>=])!(?!=)")


def _to_python(expr: str) -> str:
    s = expr.replace("&&", " and ").replace("||", " or ")
    s = _NOT_RE.sub(" not ", s)
    return s


def eval_affine(expr: str, store: dict, syms: SymbolGen) -> dict:
    node = ast.parse(_to_python(expr), mode="eval").body
    return _affine_node(node, store, syms)


def _affine_node(node, store, syms) -> dict:
    if isinstance(node, ast.Constant):
        try:
            return aff_const(int(node.value))
        except (TypeError, ValueError):
            return {}
    if isinstance(node, ast.Name):
        name = node.id
        if name in store:
            return dict(store[name])
        # Variable without a binding: treat as an unknown input symbol.
        store[name] = aff_var(syms.fresh(name))
        return dict(store[name])
    if isinstance(node, ast.Call):
        # __VERIFIER_nondet_*() or any other call -> fresh unknown symbol.
        return aff_var(syms.fresh("call"))
    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return aff_neg(_affine_node(node.operand, store, syms))
        if isinstance(node.op, ast.UAdd):
            return _affine_node(node.operand, store, syms)
        return aff_var(syms.fresh("un"))
    if isinstance(node, ast.BinOp):
        left = _affine_node(node.left, store, syms)
        right = _affine_node(node.right, store, syms)
        if isinstance(node.op, ast.Add):
            return aff_add(left, right)
        if isinstance(node.op, ast.Sub):
            return aff_sub(left, right)
        if isinstance(node.op, ast.Mult):
            if aff_is_const(left):
                return aff_scale(right, left.get(_CONST, 0))
            if aff_is_const(right):
                return aff_scale(left, right.get(_CONST, 0))
            return aff_var(syms.fresh("mul"))  # nonlinear -> unknown
        # Division, modulo, shifts, ... -> unknown (over-approximation).
        return aff_var(syms.fresh("binop"))
    # Anything else is abstracted to an unknown symbol.
    return aff_var(syms.fresh("expr"))


_FLIP = {"==": "!=", "!=": "==", "<": ">=", ">=": "<", ">": "<=", "<=": ">"}


def _cmp_rel(op, negate: bool) -> str:
    if isinstance(op, ast.Eq):
        rel = "=="
    elif isinstance(op, ast.NotEq):
        rel = "!="
    elif isinstance(op, ast.Lt):
        rel = "<"
    elif isinstance(op, ast.LtE):
        rel = "<="
    elif isinstance(op, ast.Gt):
        rel = ">"
    elif isinstance(op, ast.GtE):
        rel = ">="
    else:  # pragma: no cover - defensive
        rel = "!="
    return _FLIP[rel] if negate else rel


def eval_constraint(cond: str, store: dict, syms: SymbolGen, negate: bool = False) -> list:
    """Translate a boolean condition into a conjunction of ``(affine, op)``."""
    node = ast.parse(_to_python(cond), mode="eval").body
    return _bool_node(node, store, syms, negate)


def _bool_node(node, store, syms, negate: bool) -> list:
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            out: list = []
            for value in node.values:
                out.extend(_bool_node(value, store, syms, negate))
            return out
        # Or:  under negation it becomes a conjunction; otherwise we cannot
        # express a disjunction as a constraint set -> no constraint (unknown).
        if negate:
            out = []
            for value in node.values:
                out.extend(_bool_node(value, store, syms, True))
            return out
        return []
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return _bool_node(node.operand, store, syms, not negate)
    if isinstance(node, ast.Compare) and len(node.ops) == 1:
        left = _affine_node(node.left, store, syms)
        right = _affine_node(node.comparators[0], store, syms)
        rel = _cmp_rel(node.ops[0], negate)
        return [(aff_sub(left, right), rel)]
    # Generic truthiness test:  expr  <==>  expr != 0.
    aff = _affine_node(node, store, syms)
    return [(aff, "==" if negate else "!=")]


# ---------------------------------------------------------------------------
# Path feasibility checker (linear arithmetic over the integers)
# ---------------------------------------------------------------------------
def _substitute(affine: dict, subs: dict) -> dict:
    """Replace solved symbols in ``affine`` by their affine definitions."""
    result: dict = {}
    const = affine.get(_CONST, Fraction(0))
    if const:
        result[_CONST] = const
    for sym, coeff in affine.items():
        if sym == _CONST:
            continue
        if sym in subs:
            for s2, c2 in subs[sym].items():
                result[s2] = result.get(s2, Fraction(0)) + coeff * c2
        else:
            result[sym] = result.get(sym, Fraction(0)) + coeff
    return {k: v for k, v in result.items() if v != 0}


def _solve_equalities(equalities: list):
    """Gaussian elimination over equalities ``affine == 0``.

    Returns a substitution ``{symbol: affine}`` over the remaining free
    symbols, or ``None`` if the equalities are contradictory.
    """
    subs: dict = {}
    for eq in equalities:
        e = _substitute(eq, subs)
        symbols = [s for s in e if s != _CONST]
        if not symbols:
            if e.get(_CONST, Fraction(0)) != 0:
                return None
            continue
        sym = symbols[0]
        coeff = e[sym]
        rest = {k: v for k, v in e.items() if k != sym}
        # sym = -rest / coeff
        sym_expr = {k: -v / coeff for k, v in rest.items()}
        for key in list(subs):
            subs[key] = _substitute(subs[key], {sym: sym_expr})
        subs[sym] = sym_expr
    return subs


def _fm_feasible(inequalities: list) -> bool:
    """Fourier-Motzkin feasibility of ``affine <= 0`` constraints (rationals)."""
    constraints = [dict(c) for c in inequalities]
    while True:
        symbols = {s for c in constraints for s in c if s != _CONST}
        if not symbols:
            break
        var = symbols.pop()
        uppers, lowers, rest = [], [], []
        for c in constraints:
            coeff = c.get(var, Fraction(0))
            if coeff > 0:
                uppers.append(c)
            elif coeff < 0:
                lowers.append(c)
            else:
                rest.append(c)
        new_constraints = list(rest)
        for up in uppers:
            for low in lowers:
                factor_up = -low[var]   # > 0
                factor_low = up[var]    # > 0
                combined: dict = {}
                for s in set(up) | set(low):
                    if s == var:
                        continue
                    val = up.get(s, Fraction(0)) * factor_up + \
                        low.get(s, Fraction(0)) * factor_low
                    if val != 0:
                        combined[s] = val
                new_constraints.append(combined)
        constraints = new_constraints
    # Only constant constraints remain:  const <= 0 must hold.
    return all(c.get(_CONST, Fraction(0)) <= 0 for c in constraints)


class PathFeasibilityChecker:
    """Satisfiability checker for linear arithmetic constraints.

    Supports ``==``, ``!=``, ``<``, ``<=``, ``>``, ``>=`` and ``+``, ``-`` and
    multiplication by constants.  Strict inequalities and disequalities use the
    fact that symbols range over the integers.
    """

    def satisfiable(self, constraints: list) -> bool:
        equalities: list = []
        inequalities: list = []   # affine <= 0
        disequalities: list = []  # affine != 0

        for affine, op in constraints:
            a = {k: Fraction(v) for k, v in affine.items()}
            if op == "==":
                equalities.append(a)
            elif op == "!=":
                disequalities.append(a)
            elif op == "<=":
                inequalities.append(a)
            elif op == ">=":
                inequalities.append(aff_neg(a))
            elif op == "<":
                inequalities.append(aff_add_const(a, 1))
            elif op == ">":
                inequalities.append(aff_add_const(aff_neg(a), 1))
            else:  # pragma: no cover - defensive
                return True

        subs = _solve_equalities(equalities)
        if subs is None:
            return False

        inequalities = [_substitute(i, subs) for i in inequalities]
        disequalities = [_substitute(d, subs) for d in disequalities]

        remaining_diseq = []
        for d in disequalities:
            if aff_is_const(d):
                if d.get(_CONST, Fraction(0)) == 0:
                    return False  # 0 != 0 is contradictory
                # constant != 0 is always satisfied -> drop
            else:
                remaining_diseq.append(d)

        if not _fm_feasible(inequalities):
            return False

        # A disequality d != 0 is unsatisfiable iff the inequality system
        # forces d == 0, i.e. neither d >= 1 nor d <= -1 is feasible.
        for d in remaining_diseq:
            d_ge = aff_add_const(aff_neg(d), 1)   # d >= 1
            d_le = aff_add_const(d, 1)            # d <= -1
            if not _fm_feasible(inequalities + [d_ge]) and \
               not _fm_feasible(inequalities + [d_le]):
                return False
        return True

    def entails(self, constraints: list, extra: list) -> bool:
        """True iff ``constraints`` logically imply ``extra`` (a conjunction)."""
        # constraints ==> extra  iff  constraints AND NOT extra is UNSAT.
        negated: list = []
        for affine, op in extra:
            negated.append((affine, _FLIP[op]))
        # Any one of the negated constraints being forced makes extra false;
        # extra is entailed iff *every* way of violating it is infeasible.
        return all(
            not self.satisfiable(list(constraints) + [neg]) for neg in negated
        )


# ---------------------------------------------------------------------------
# Predicate abstract state
# ---------------------------------------------------------------------------
def _canon_aff(a: dict):
    return tuple(sorted(a.items()))


def _canon_store(store: dict):
    return tuple(sorted((v, _canon_aff(a)) for v, a in store.items()))


def _canon_constraints(constraints) -> tuple:
    return tuple(sorted((_canon_aff(a), op) for a, op in constraints))


class PredicateAbstractState(AbstractState):
    """Symbolic store + path constraints + derived predicate signature."""

    def __init__(self, store: dict, constraints, signature):
        self.store = {v: dict(a) for v, a in store.items()}
        self.constraints = tuple(constraints)
        self.signature = frozenset(signature)

    def assign(self, var: str, value: dict) -> "PredicateAbstractState":
        new_store = {v: dict(a) for v, a in self.store.items()}
        new_store[var] = dict(value)
        return PredicateAbstractState(new_store, self.constraints, self.signature)

    def with_constraints(self, extra, signature) -> "PredicateAbstractState":
        return PredicateAbstractState(self.store,
                                      self.constraints + tuple(extra),
                                      signature)

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, PredicateAbstractState)
            and _canon_store(self.store) == _canon_store(other.store)
            and _canon_constraints(self.constraints) == _canon_constraints(other.constraints)
            and self.signature == other.signature
        )

    def __hash__(self) -> int:
        return hash((
            _canon_store(self.store),
            _canon_constraints(self.constraints),
            self.signature,
        ))

    def __repr__(self) -> str:
        store_str = ", ".join(f"{v}={_aff_str(a)}" for v, a in sorted(self.store.items()))
        return f"PredState(store={{{store_str}}}, sig={sorted(self.signature)})"


def _aff_str(a: dict) -> str:
    parts = []
    for sym, coeff in sorted(a.items()):
        if sym == _CONST:
            parts.append(str(coeff))
        else:
            parts.append(f"{coeff}*{sym}")
    return " + ".join(parts) if parts else "0"


# ---------------------------------------------------------------------------
# Predicate CPA components
# ---------------------------------------------------------------------------
class PredicateDomain(AbstractDomain):
    def is_less_or_equal(self, state1, state2) -> bool:
        # state1 ⊑ state2 iff state2 knows a subset of state1's predicates
        # (state2 is weaker, hence covers state1).
        return state2.signature <= state1.signature

    def join(self, state1, state2):  # pragma: no cover - merge is "sep"
        return state2 if state1.signature <= state2.signature else state1

    def get_top(self):
        return PredicateAbstractState({}, [], frozenset())

    def get_bottom(self):  # pragma: no cover - not used
        return None


class PredicateTransferRelation(TransferRelation):
    """Strongest-postcondition transfer over the symbolic domain."""

    def __init__(self, predicates, checker: PathFeasibilityChecker, syms: SymbolGen):
        self._predicates = list(predicates)
        self._checker = checker
        self._syms = syms

    # -- signature computation ---------------------------------------------
    def _signature(self, store: dict, constraints) -> frozenset:
        signature = set()
        base = list(constraints)
        for pred in self._predicates:
            true_cons = eval_constraint(pred, dict(store), self._syms, negate=False)
            false_cons = eval_constraint(pred, dict(store), self._syms, negate=True)
            if not self._checker.satisfiable(base + false_cons):
                signature.add((pred, True))
            elif not self._checker.satisfiable(base + true_cons):
                signature.add((pred, False))
        return frozenset(signature)

    def get_abstract_successors(self, state, precision, edge):
        etype = edge.edge_type

        if etype == EdgeType.ASSIGNMENT:
            store = {v: dict(a) for v, a in state.store.items()}
            value = eval_affine(edge.expression, store, self._syms)
            store[edge.variable] = value
            signature = self._signature(store, state.constraints)
            return [PredicateAbstractState(store, state.constraints, signature)]

        if etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            negate = etype == EdgeType.ASSUME_FALSE
            store = {v: dict(a) for v, a in state.store.items()}
            extra = eval_constraint(edge.expression, store, self._syms, negate=negate)
            new_constraints = list(state.constraints) + extra
            if not self._checker.satisfiable(new_constraints):
                return []  # infeasible path
            signature = self._signature(store, new_constraints)
            return [PredicateAbstractState(store, new_constraints, signature)]

        # ASSERT / FUNCTION_CALL / BLANK: valuation and constraints unchanged.
        return [PredicateAbstractState(state.store, state.constraints, state.signature)]


class PredicateMergeOperator(MergeOperator):
    """"sep" semantics: keep every path separate for precision."""

    def merge(self, state1, state2, precision):
        return state2


class PredicateStopOperator(StopOperator):
    def __init__(self, domain: PredicateDomain):
        self._domain = domain

    def stop(self, state, reached, precision):
        return any(self._domain.is_less_or_equal(state, r) for r in reached)


class PredicateCPA(ConfigurableProgramAnalysis):
    def __init__(self, cfa: CFA):
        self._variables = list(cfa.variables)
        self._checker = PathFeasibilityChecker()
        self._syms = SymbolGen()
        self._predicates = _extract_predicates(cfa)
        self._domain = PredicateDomain()
        self._transfer = PredicateTransferRelation(
            self._predicates, self._checker, self._syms)
        self._merge = PredicateMergeOperator()
        self._stop = PredicateStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        # Every variable starts as an unconstrained input symbol.
        store = {v: aff_var(self._syms.fresh(v)) for v in self._variables}
        signature = self._transfer._signature(store, [])
        return PredicateAbstractState(store, [], signature)

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


def _extract_predicates(cfa: CFA) -> list:
    """Collect the distinct assume-edge conditions as the predicate set."""
    seen: list = []
    for edge in cfa.edges:
        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            expr = edge.expression.strip()
            if expr and expr not in seen:
                seen.append(expr)
    return seen


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def run_predicate_analysis(cfa: CFA, timelimit: int = 900) -> VerificationResult:
    """Run predicate analysis on ``cfa`` and return the verdict."""
    cpa = CompositeCPA([LocationCPA(), PredicateCPA(cfa)])
    result = cpa_algorithm(cpa, cfa, timelimit)
    result.statistics.setdefault("analysis", "predicateAnalysis")
    result.statistics.setdefault("predicates", len(_extract_predicates(cfa)))
    return result

display.content:
"""Predicate analysis with symbolic constraints and path-feasibility checking.

This module implements cpachecker_v1.

Instead of tracking concrete values, the predicate analysis performs *symbolic
execution*: every program variable maps to an affine expression over input
symbols (one fresh symbol per ``__VERIFIER_nondet_*`` call), and every assume
edge adds a path constraint.  A lightweight constraint solver
(:class:`PathFeasibilityChecker`) decides satisfiability of the accumulated
linear arithmetic constraints, which is used both for pruning infeasible paths
and for deciding whether an error location is reachable.

Termination on loops is achieved through a *predicate abstraction* layer: from
the precise symbolic state we derive, for a fixed set of program predicates
(the conditions occurring in the CFA), which of them are known to hold.  A
state is subsumed (coverage / stop operator) as soon as a previously explored
state at the same location knows a subset of these predicates.

Components:

- :class:`PathFeasibilityChecker`  - linear-arithmetic satisfiability checker.
- :class:`PredicateAbstractState`  - symbolic store + path constraints.
- :class:`PredicateTransferRelation` - strongest-postcondition style transfer.
- :class:`PredicateCPA`            - the CPA wrapping the above.
- :func:`run_predicate_analysis`   - entry point.
"""

from __future__ import annotations

import ast
import re
from fractions import Fraction

from cpachecker.cfa import CFA, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.analyses.value_analysis import (
    CompositeCPA,
    EmptyPrecision,
    LocationCPA,
    cpa_algorithm,
)
from cpachecker.result import Verdict, VerificationResult

_CONST = ""  # reserved key holding the constant summand of an affine form


# ---------------------------------------------------------------------------
# Affine forms: dict {symbol: coeff, _CONST: const}
# ---------------------------------------------------------------------------
def aff_const(c: int) -> dict:
    return {_CONST: c} if c != 0 else {}


def aff_var(symbol: str) -> dict:
    return {symbol: 1}


def aff_neg(a: dict) -> dict:
    return {k: -v for k, v in a.items()}


def _clean(a: dict) -> dict:
    return {k: v for k, v in a.items() if v != 0}


def aff_add(a: dict, b: dict) -> dict:
    r = dict(a)
    for k, v in b.items():
        r[k] = r.get(k, 0) + v
    return _clean(r)


def aff_sub(a: dict, b: dict) -> dict:
    return aff_add(a, aff_neg(b))


def aff_scale(a: dict, k: int) -> dict:
    if k == 0:
        return {}
    return _clean({key: v * k for key, v in a.items()})


def aff_add_const(a: dict, c) -> dict:
    r = dict(a)
    r[_CONST] = r.get(_CONST, 0) + c
    return _clean(r)


def aff_is_const(a: dict) -> bool:
    return all(k == _CONST for k in a)


# ---------------------------------------------------------------------------
# Symbol generation
# ---------------------------------------------------------------------------
class SymbolGen:
    """Produces fresh symbols for nondeterministic / unknown values."""

    def __init__(self) -> None:
        self._counter = 0

    def fresh(self, prefix: str = "s") -> str:
        self._counter += 1
        return f"#{prefix}{self._counter}"


# ---------------------------------------------------------------------------
# Expression -> affine form / constraint (via the ``ast`` module)
# ---------------------------------------------------------------------------
_NOT_RE = re.compile(r"(?<![!<>=])!(?!=)")


def _to_python(expr: str) -> str:
    s = expr.replace("&&", " and ").replace("||", " or ")
    s = _NOT_RE.sub(" not ", s)
    return s


def eval_affine(expr: str, store: dict, syms: SymbolGen) -> dict:
    node = ast.parse(_to_python(expr), mode="eval").body
    return _affine_node(node, store, syms)


def _affine_node(node, store, syms) -> dict:
    if isinstance(node, ast.Constant):
        try:
            return aff_const(int(node.value))
        except (TypeError, ValueError):
            return {}
    if isinstance(node, ast.Name):
        name = node.id
        if name in store:
            return dict(store[name])
        # Variable without a binding: treat as an unknown input symbol.
        store[name] = aff_var(syms.fresh(name))
        return dict(store[name])
    if isinstance(node, ast.Call):
        # __VERIFIER_nondet_*() or any other call -> fresh unknown symbol.
        return aff_var(syms.fresh("call"))
    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return aff_neg(_affine_node(node.operand, store, syms))
        if isinstance(node.op, ast.UAdd):
            return _affine_node(node.operand, store, syms)
        return aff_var(syms.fresh("un"))
    if isinstance(node, ast.BinOp):
        left = _affine_node(node.left, store, syms)
        right = _affine_node(node.right, store, syms)
        if isinstance(node.op, ast.Add):
            return aff_add(left, right)
        if isinstance(node.op, ast.Sub):
            return aff_sub(left, right)
        if isinstance(node.op, ast.Mult):
            if aff_is_const(left):
                return aff_scale(right, left.get(_CONST, 0))
            if aff_is_const(right):
                return aff_scale(left, right.get(_CONST, 0))
            return aff_var(syms.fresh("mul"))  # nonlinear -> unknown
        # Division, modulo, shifts, ... -> unknown (over-approximation).
        return aff_var(syms.fresh("binop"))
    # Anything else is abstracted to an unknown symbol.
    return aff_var(syms.fresh("expr"))


_FLIP = {"==": "!=", "!=": "==", "<": ">=", ">=": "<", ">": "<=", "<=": ">"}


def _cmp_rel(op, negate: bool) -> str:
    if isinstance(op, ast.Eq):
        rel = "=="
    elif isinstance(op, ast.NotEq):
        rel = "!="
    elif isinstance(op, ast.Lt):
        rel = "<"
    elif isinstance(op, ast.LtE):
        rel = "<="
    elif isinstance(op, ast.Gt):
        rel = ">"
    elif isinstance(op, ast.GtE):
        rel = ">="
    else:  # pragma: no cover - defensive
        rel = "!="
    return _FLIP[rel] if negate else rel


def eval_constraint(cond: str, store: dict, syms: SymbolGen, negate: bool = False) -> list:
    """Translate a boolean condition into a conjunction of ``(affine, op)``."""
    node = ast.parse(_to_python(cond), mode="eval").body
    return _bool_node(node, store, syms, negate)


def _bool_node(node, store, syms, negate: bool) -> list:
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            out: list = []
            for value in node.values:
                out.extend(_bool_node(value, store, syms, negate))
            return out
        # Or:  under negation it becomes a conjunction; otherwise we cannot
        # express a disjunction as a constraint set -> no constraint (unknown).
        if negate:
            out = []
            for value in node.values:
                out.extend(_bool_node(value, store, syms, True))
            return out
        return []
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return _bool_node(node.operand, store, syms, not negate)
    if isinstance(node, ast.Compare) and len(node.ops) == 1:
        left = _affine_node(node.left, store, syms)
        right = _affine_node(node.comparators[0], store, syms)
        rel = _cmp_rel(node.ops[0], negate)
        return [(aff_sub(left, right), rel)]
    # Generic truthiness test:  expr  <==>  expr != 0.
    aff = _affine_node(node, store, syms)
    return [(aff, "==" if negate else "!=")]


# ---------------------------------------------------------------------------
# Path feasibility checker (linear arithmetic over the integers)
# ---------------------------------------------------------------------------
def _substitute(affine: dict, subs: dict) -> dict:
    """Replace solved symbols in ``affine`` by their affine definitions."""
    result: dict = {}
    const = affine.get(_CONST, Fraction(0))
    if const:
        result[_CONST] = const
    for sym, coeff in affine.items():
        if sym == _CONST:
            continue
        if sym in subs:
            for s2, c2 in subs[sym].items():
                result[s2] = result.get(s2, Fraction(0)) + coeff * c2
        else:
            result[sym] = result.get(sym, Fraction(0)) + coeff
    return {k: v for k, v in result.items() if v != 0}


def _solve_equalities(equalities: list):
    """Gaussian elimination over equalities ``affine == 0``.

    Returns a substitution ``{symbol: affine}`` over the remaining free
    symbols, or ``None`` if the equalities are contradictory.
    """
    subs: dict = {}
    for eq in equalities:
        e = _substitute(eq, subs)
        symbols = [s for s in e if s != _CONST]
        if not symbols:
            if e.get(_CONST, Fraction(0)) != 0:
                return None
            continue
        sym = symbols[0]
        coeff = e[sym]
        rest = {k: v for k, v in e.items() if k != sym}
        # sym = -rest / coeff
        sym_expr = {k: -v / coeff for k, v in rest.items()}
        for key in list(subs):
            subs[key] = _substitute(subs[key], {sym: sym_expr})
        subs[sym] = sym_expr
    return subs


def _fm_feasible(inequalities: list) -> bool:
    """Fourier-Motzkin feasibility of ``affine <= 0`` constraints (rationals)."""
    constraints = [dict(c) for c in inequalities]
    while True:
        symbols = {s for c in constraints for s in c if s != _CONST}
        if not symbols:
            break
        var = symbols.pop()
        uppers, lowers, rest = [], [], []
        for c in constraints:
            coeff = c.get(var, Fraction(0))
            if coeff > 0:
                uppers.append(c)
            elif coeff < 0:
                lowers.append(c)
            else:
                rest.append(c)
        new_constraints = list(rest)
        for up in uppers:
            for low in lowers:
                factor_up = -low[var]   # > 0
                factor_low = up[var]    # > 0
                combined: dict = {}
                for s in set(up) | set(low):
                    if s == var:
                        continue
                    val = up.get(s, Fraction(0)) * factor_up + \
                        low.get(s, Fraction(0)) * factor_low
                    if val != 0:
                        combined[s] = val
                new_constraints.append(combined)
        constraints = new_constraints
    # Only constant constraints remain:  const <= 0 must hold.
    return all(c.get(_CONST, Fraction(0)) <= 0 for c in constraints)


class PathFeasibilityChecker:
    """Satisfiability checker for linear arithmetic constraints.

    Supports ``==``, ``!=``, ``<``, ``<=``, ``>``, ``>=`` and ``+``, ``-`` and
    multiplication by constants.  Strict inequalities and disequalities use the
    fact that symbols range over the integers.
    """

    def satisfiable(self, constraints: list) -> bool:
        equalities: list = []
        inequalities: list = []   # affine <= 0
        disequalities: list = []  # affine != 0

        for affine, op in constraints:
            a = {k: Fraction(v) for k, v in affine.items()}
            if op == "==":
                equalities.append(a)
            elif op == "!=":
                disequalities.append(a)
            elif op == "<=":
                inequalities.append(a)
            elif op == ">=":
                inequalities.append(aff_neg(a))
            elif op == "<":
                inequalities.append(aff_add_const(a, 1))
            elif op == ">":
                inequalities.append(aff_add_const(aff_neg(a), 1))
            else:  # pragma: no cover - defensive
                return True

        subs = _solve_equalities(equalities)
        if subs is None:
            return False

        inequalities = [_substitute(i, subs) for i in inequalities]
        disequalities = [_substitute(d, subs) for d in disequalities]

        remaining_diseq = []
        for d in disequalities:
            if aff_is_const(d):
                if d.get(_CONST, Fraction(0)) == 0:
                    return False  # 0 != 0 is contradictory
                # constant != 0 is always satisfied -> drop
            else:
                remaining_diseq.append(d)

        if not _fm_feasible(inequalities):
            return False

        # A disequality d != 0 is unsatisfiable iff the inequality system
        # forces d == 0, i.e. neither d >= 1 nor d <= -1 is feasible.
        for d in remaining_diseq:
            d_ge = aff_add_const(aff_neg(d), 1)   # d >= 1
            d_le = aff_add_const(d, 1)            # d <= -1
            if not _fm_feasible(inequalities + [d_ge]) and \
               not _fm_feasible(inequalities + [d_le]):
                return False
        return True

    def entails(self, constraints: list, extra: list) -> bool:
        """True iff ``constraints`` logically imply ``extra`` (a conjunction)."""
        # constraints ==> extra  iff  constraints AND NOT extra is UNSAT.
        negated: list = []
        for affine, op in extra:
            negated.append((affine, _FLIP[op]))
        # Any one of the negated constraints being forced makes extra false;
        # extra is entailed iff *every* way of violating it is infeasible.
        return all(
            not self.satisfiable(list(constraints) + [neg]) for neg in negated
        )


# ---------------------------------------------------------------------------
# Predicate abstract state
# ---------------------------------------------------------------------------
def _canon_aff(a: dict):
    return tuple(sorted(a.items()))


def _canon_store(store: dict):
    return tuple(sorted((v, _canon_aff(a)) for v, a in store.items()))


def _canon_constraints(constraints) -> tuple:
    return tuple(sorted((_canon_aff(a), op) for a, op in constraints))


class PredicateAbstractState(AbstractState):
    """Symbolic store + path constraints + derived predicate signature."""

    def __init__(self, store: dict, constraints, signature):
        self.store = {v: dict(a) for v, a in store.items()}
        self.constraints = tuple(constraints)
        self.signature = frozenset(signature)

    def assign(self, var: str, value: dict) -> "PredicateAbstractState":
        new_store = {v: dict(a) for v, a in self.store.items()}
        new_store[var] = dict(value)
        return PredicateAbstractState(new_store, self.constraints, self.signature)

    def with_constraints(self, extra, signature) -> "PredicateAbstractState":
        return PredicateAbstractState(self.store,
                                      self.constraints + tuple(extra),
                                      signature)

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, PredicateAbstractState)
            and _canon_store(self.store) == _canon_store(other.store)
            and _canon_constraints(self.constraints) == _canon_constraints(other.constraints)
            and self.signature == other.signature
        )

    def __hash__(self) -> int:
        return hash((
            _canon_store(self.store),
            _canon_constraints(self.constraints),
            self.signature,
        ))

    def __repr__(self) -> str:
        store_str = ", ".join(f"{v}={_aff_str(a)}" for v, a in sorted(self.store.items()))
        return f"PredState(store={{{store_str}}}, sig={sorted(self.signature)})"


def _aff_str(a: dict) -> str:
    parts = []
    for sym, coeff in sorted(a.items()):
        if sym == _CONST:
            parts.append(str(coeff))
        else:
            parts.append(f"{coeff}*{sym}")
    return " + ".join(parts) if parts else "0"


# ---------------------------------------------------------------------------
# Predicate CPA components
# ---------------------------------------------------------------------------
class PredicateDomain(AbstractDomain):
    def is_less_or_equal(self, state1, state2) -> bool:
        # state1 ⊑ state2 iff state2 knows a subset of state1's predicates
        # (state2 is weaker, hence covers state1).
        return state2.signature <= state1.signature

    def join(self, state1, state2):  # pragma: no cover - merge is "sep"
        return state2 if state1.signature <= state2.signature else state1

    def get_top(self):
        return PredicateAbstractState({}, [], frozenset())

    def get_bottom(self):  # pragma: no cover - not used
        return None


class PredicateTransferRelation(TransferRelation):
    """Strongest-postcondition transfer over the symbolic domain."""

    def __init__(self, predicates, checker: PathFeasibilityChecker, syms: SymbolGen):
        self._predicates = list(predicates)
        self._checker = checker
        self._syms = syms

    # -- signature computation ---------------------------------------------
    def _signature(self, store: dict, constraints) -> frozenset:
        signature = set()
        base = list(constraints)
        for pred in self._predicates:
            true_cons = eval_constraint(pred, dict(store), self._syms, negate=False)
            false_cons = eval_constraint(pred, dict(store), self._syms, negate=True)
            if not self._checker.satisfiable(base + false_cons):
                signature.add((pred, True))
            elif not self._checker.satisfiable(base + true_cons):
                signature.add((pred, False))
        return frozenset(signature)

    def get_abstract_successors(self, state, precision, edge):
        etype = edge.edge_type

        if etype == EdgeType.ASSIGNMENT:
            store = {v: dict(a) for v, a in state.store.items()}
            value = eval_affine(edge.expression, store, self._syms)
            store[edge.variable] = value
            signature = self._signature(store, state.constraints)
            return [PredicateAbstractState(store, state.constraints, signature)]

        if etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            negate = etype == EdgeType.ASSUME_FALSE
            store = {v: dict(a) for v, a in state.store.items()}
            extra = eval_constraint(edge.expression, store, self._syms, negate=negate)
            new_constraints = list(state.constraints) + extra
            if not self._checker.satisfiable(new_constraints):
                return []  # infeasible path
            signature = self._signature(store, new_constraints)
            return [PredicateAbstractState(store, new_constraints, signature)]

        # ASSERT / FUNCTION_CALL / BLANK: valuation and constraints unchanged.
        return [PredicateAbstractState(state.store, state.constraints, state.signature)]


class PredicateMergeOperator(MergeOperator):
    """"sep" semantics: keep every path separate for precision."""

    def merge(self, state1, state2, precision):
        return state2


class PredicateStopOperator(StopOperator):
    def __init__(self, domain: PredicateDomain):
        self._domain = domain

    def stop(self, state, reached, precision):
        return any(self._domain.is_less_or_equal(state, r) for r in reached)


class PredicateCPA(ConfigurableProgramAnalysis):
    def __init__(self, cfa: CFA):
        self._variables = list(cfa.variables)
        self._checker = PathFeasibilityChecker()
        self._syms = SymbolGen()
        self._predicates = _extract_predicates(cfa)
        self._domain = PredicateDomain()
        self._transfer = PredicateTransferRelation(
            self._predicates, self._checker, self._syms)
        self._merge = PredicateMergeOperator()
        self._stop = PredicateStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        # Every variable starts as an unconstrained input symbol.
        store = {v: aff_var(self._syms.fresh(v)) for v in self._variables}
        signature = self._transfer._signature(store, [])
        return PredicateAbstractState(store, [], signature)

    def get_initial_precision(self) -> Precision:
        return EmptyPrecision()


def _extract_predicates(cfa: CFA) -> list:
    """Collect the distinct assume-edge conditions as the predicate set."""
    seen: list = []
    for edge in cfa.edges:
        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            expr = edge.expression.strip()
            if expr and expr not in seen:
                seen.append(expr)
    return seen


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def run_predicate_analysis(cfa: CFA, timelimit: int = 900) -> VerificationResult:
    """Run predicate analysis on ``cfa`` and return the verdict."""
    cpa = CompositeCPA([LocationCPA(), PredicateCPA(cfa)])
    result = cpa_algorithm(cpa, cfa, timelimit)
    result.statistics.setdefault("analysis", "predicateAnalysis")
    result.statistics.setdefault("predicates", len(_extract_predicates(cfa)))
    return result
